SELECT
FROM service_item si INNER JOIN service_category sc ON sc.id = si.category_id WHERE
ORDER BY si.sort_order ASC, si.id ASC LIMIT #{limit}

SELECT
FROM service_item si INNER JOIN service_category sc ON sc.id = si.category_id WHERE
AND (si.name LIKE CONCAT('%', #{keyword}, '%') OR si.description LIKE CONCAT('%', #{keyword}, '%')) ORDER BY si.sort_order ASC, si.id ASC LIMIT #{limit}
